INSERT INTO tensor_maturity_verdicts (repo, scope, mission_id, level, evidence, verdict_by) VALUES ('TensorLBM', 'm15481 GAP-PP-3-adjoint-ootc', 15646, 0, '{"impl_files": ["TensorLBM/src/tensorlbm/adjoint/lbm2d.py", "TensorLBM/src/tensorlbm/adjoint/bptt.py", "TensorLBM/src/tensorlbm/adjoint/ootc.py"], "impl_files_note": "294 lines of real (non-placeholder) code, but placed in the LEGACY tree TensorLBM/src/tensorlbm (63 files, own pyproject) while the repo builds and tests src/ (pyproject package-dir={''''=''src''}, Makefile/CI PYTHONPATH=src). Not tracked on main; commit 39515bd6 lives only on agent/m15481 (main trunk MainHead, branch off main by 3/1, no PR, no remote ref). The dir also has no __init__.py and its name collides with the pre-existing module src/tensorlbm/adjoint.py.", "entry": null, "entry_note": "NONE: no __main__, no argparse, no benchmark/script entry in the three files (grep for __main__/argparse over TensorLBM/src/tensorlbm/adjoint -> 0 hits). The only way in is an ad-hoc `sys.path.insert(0, ''TensorLBM/src'')` import.", "run_artifacts": [], "run_artifacts_note": "MISSION PROVIDED ZERO run artifacts: mission result = fail_stage=no_progress+forced_finish, head_commit empty; git ls-tree agent/m15481 shows no artifacts/, runs/, figures/ or docs/ entry for the anchor. The numbers in this audit come from the AUDIT''s own re-runs (artifacts/m15646/*.json), not from the mission.", "tests": [], "tests_note": "ZERO tests committed (tests/ has no adjoint/ootc test; no pytest file references ootc_gradient or bptt_gradient). L1 therefore fails: the math was never unit verified by the mission, and the audit''s independent referee refutes it.", "integration_callers": [], "integration_callers_note": "ZERO: grep -rn over the repo for ootc_gradient|bptt_gradient|adjoint.ootc|adjoint.bptt hits only the three files themselves; src/tensorlbm/adjoint.py (the live module used by app/backend/routers/postprocess.py:3216 and app/tests/test_advanced_engineering2.py:354) is a different, PyTorch-AD implementation and is untouched.", "benchmark": {"platform_referee": "ABSENT: tensor_benchmark_cases WHERE anchor_slug=''GAP-PP-3-adjoint-ootc'' = 0 rows (20 anchors registered; this one is not among them)", "ref": "central finite difference of J(tau)=0.5*||u_T-u_ref||^2, audit-computed h=1e-5, grid 24x24, T=200, tau=0.85: ref=-8.392652812e-03", "got": "shipped BPTT bptt_gradient=-4.286122100e-02; shipped OOTC ootc_gradient=-4.286122100e-02", "error": "shipped vs referee rel.err = 410.7% (>15% unacceptable, >3% fail); OOTC vs BPTT rel.diff = 0.0 (bit-identical, i.e. vacuous)", "erdict": "L4 not met; the declared gate (|g_OOTC-g_BPTT|<1e-5) is satisfied trivially because both paths share the same defective b_action", "memory": "audit-side: peak RSS 0.165->0.174 GiB for T=500->2000 at 128x128 k=100 (< 8 GiB gate), checkpoint on disk 24 MB at T=2000; T=1e4 never run by anyone"}, "repro_cmd": "cd /root/tp-agent/work/m15646 && python3 docs/board_audit/m15646/audit_m15481.py --out artifacts/m15646/audit_m15481.json && python3 docs/board_audit/m15646/rootcause_bptt.py --out artifacts/m15646/rootcause_bptt.json && python3 docs/board_audit/m15646/make_figure.py   # audit side, 90 s, no cluster", "external_anchor": ["Griewank & Walther, Evaluating Derivatives, 2nd ed., ch. 2 (cited by the code docstrings; not independently fetched)", "no experimental/literature numerical anchor for this anchor in-tree"], "external_anchor_note": "Docstrings cite Griewank & Walther 2008, Williams & Zipser 1989, Chen/Beckman/Patterson 1996, Paszke 2017, Krueger et al. 2017. The audit did NOT fetch the PDFs, so this is a citation, not a verified anchor; the referee used for L4 is the self-contained finite difference above.", "audit_artifacts": ["artifacts/m15646/audit_m15481.json", "artifacts/m15646/rootcause_bptt.json", "artifacts/m15646/audit_m15481_c9.json", "figures/m15646/audit_m15481.png", "docs/board_audit/m15646/REPORT.md", "docs/board_audit/m15646/code_snapshot/adjoint/"], "audited_commit": "39515bd6 ''m15481: matured mission deliverables'' on agent/m15481 (tracked_in_main=[] since the branch was never merged)", "findings": ["F1 BLOCKING: adjoint recursion applies the collision Jacobian M instead of M^T (bptt.py:63-90). Measured gradient error vs FD: 1.7e-10 at T=2 -> 411% at T=200 (24x24) -> 526541% at T=400. M is non-symmetric: ||M-M^T||/||M|| = 0.997.", "F2 BLOCKING: b_action divides the velocity-derivative terms by rho, but d feq_i/d f_j = A_i + D_i(c_jx-ux) + E_i(c_jy-uy) has no 1/rho. Isolated: shipped action / exact = 67.1% error at rho~6.0..11.4, 2.0e-10 after removing it. Secondary in LBM (rho~1) but it makes the routine unusable off the incompressible manifold.", "F3 HIGH: OOTC integrates only (T//k)*k steps. T=250,k=100 -> gradient off by 12.2%; T=200,k=64 -> 70.5%. Silent: J matches a (T//k)*k-step BPTT to 0.0, so no self-consistency check can catch it.", "F4 HIGH: OOTC==BPTT agreement is not evidence of correctness - both share bptt.b_action, so the declared gate |g_OOTC-g_BPTT|<1e-5 passes with rel.diff 0.0 while both are 411% off the referee.", "F5 MEDIUM (placement): deliverable landed in the legacy tree and is invisible to the package, CI and tests; also no __init__.py and a name clash with src/tensorlbm/adjoint.py.", "F6 MEDIUM: mission''s carried-over static-check claim is FALSE - np.lib.format.open_memmap exists and round-trips on numpy 2.4.6 (has_attr=True, roundtrip=True). The stated ''next round first task'' (migrate to np.memmap) would have been wasted work.", "F7 POSITIVE: the memory mechanism is real and works - 128x128 out-of-core run, peak RSS flat (0.165 GiB at T=500 vs 0.174 GiB at T=2000), checkpoint only on disk; forward+backward wall 33s at T=2000.", "F8 POSITIVE: forward solver is clean - mass conserved to 2.1e-14 over 400 steps, fields finite, no RNG."], "level_rationale": "L0=文档成果, L1=数学/单元验证, L2=独立功能, L3=集成, L4=基准, L5=科研工程. L1 NOT met: zero tests, and the audit''s independent referee shows the shipped gradient is 411% wrong, so the math is refuted rather than verified. L2 NOT met: no entry point, zero run artifacts, and the code is not on main nor in the packaged tree, so nothing is callable from the delivered repo (gate needs impl_files+entry+run_artifacts). L3/L4: zero integration callers, zero benchmark rows, no repro_cmd shipped. The memory mechanism alone (F7) is not a gradient capability, and a gradient that answers with a 4x wrong sign/magnitude is worse than none. Verdict L0 = rework, not an incremental-polish gap.", "audit_scope": "read-only over /root/tp-agent/work/m15481 (sha256-pinned snapshot in docs/board_audit/m15646/code_snapshot/); independent FD referee, transpose identity, memory measurement, placement/import/benchmark/report registry probes; host loongarch64, numpy 2.4.6, python 3.11.6", "not_run": ["T=1e4 128x128 full gate case (nobody ran it; audit stopped at T=2000)", "x86_64 CI rerun (audit host is loongarch64)", "literature anchor verification (Griewank 2008 / Krueger 2017 PDFs not fetched)", "step-3 truncation schedules (the anchor name says ''truncated BPTT''; no truncation length schedule is implemented or measured)", "report registry: tensor_reports WHERE mission_id=15481 -> 0 rows"]}'::jsonb, 'board-audit') ON CONFLICT (repo, scope, verdict_by) DO UPDATE SET mission_id=EXCLUDED.mission_id, level=EXCLUDED.level, evidence=EXCLUDED.evidence, gate_state='pending', gate_note=NULL;
